const now = new Date();
const parts = new Intl.DateTimeFormat('en-US', {
  timeZone: 'Asia/Manila',
  weekday: 'short',
  hour: '2-digit',
  minute: '2-digit',
  hourCycle: 'h23'
}).formatToParts(now);
const value = (type) => parts.find((part) => part.type === type)?.value;

return [{
  json: {
    employee: 'Benjie Lipalam',
    weekday: value('weekday'),
    hour: Number(value('hour')),
    minute: Number(value('minute')),
    timezone: 'Asia/Manila',
    checkedAt: now.toISOString()
  }
}];

return items.map(({ json }) => {
  const weekday = !['Sat', 'Sun'].includes(json.weekday);
  const minutes = json.hour * 60 + json.minute;
  const clockIn = minutes >= 480 && minutes <= 555;
  const clockOut = minutes >= 1020 && minutes <= 1095;
  const action = weekday && clockIn ? 'CLOCK_IN' : weekday && clockOut ? 'CLOCK_OUT' : 'HOLD';

  return {
    json: {
      ...json,
      action,
      validWindow: action !== 'HOLD',
      explanation: action === 'HOLD' ? 'Outside the approved time windows; no action is taken.' : `Validated ${action.replace('_', ' ').toLowerCase()} window.`
    }
  };
});

return items.map(({ json }) => ({
  json: {
    ...json,
    auditStatus: 'Ready for attendance API',
    auditMessage: `${json.action} validated for ${json.employee}.`
  }
}));

return items.map(({ json }) => ({
  json: {
    ...json,
    auditStatus: 'No action',
    auditMessage: json.explanation
  }
}));
